namespace {int allocation_after=-1;NativeMoviePlaybackContext* reentry_target=nullptr;bool reentry_checked=false;}
void* operator new(std::size_t n){if(reentry_target){auto* owner=reentry_target;reentry_target=nullptr;MovieControlFailure a,b;const bool stopped=owner->stop(a);const auto snapshot=owner->snapshot(b);reentry_checked=!stopped&&!snapshot&&a.kind==MovieControlError::invalid_state&&b.kind==MovieControlError::invalid_state;}if(allocation_after==0){allocation_after=-1;throw std::bad_alloc();}if(allocation_after>0)--allocation_after;if(auto* p=std::malloc(n?n:1))return p;throw std::bad_alloc();}
