using Bytes=std::vector<std::uint8_t>;
void check(bool value,const char* text){if(!value)throw std::runtime_error(text);}
struct Bits {Bytes bytes;unsigned bit=0;explicit Bits(unsigned code):bytes{0,0,1,std::uint8_t(code)}{}void put(unsigned n,std::uint32_t value){for(unsigned i=0;i<n;++i){if(!bit)bytes.push_back(0);bytes.back()|=((value>>(n-1-i))&1u)<<(7-bit);bit=(bit+1)%8;}}};
Bytes sequence(unsigned rate){Bits b(0xb3);b.put(12,640);b.put(12,448);b.put(4,3);b.put(4,rate);b.put(18,1);b.put(1,1);b.put(10,112);b.put(1,0);b.put(1,0);b.put(1,0);return b.bytes;}
Bytes extension(){Bits b(0xb5);b.put(4,1);b.put(8,0x48);b.put(1,1);b.put(2,1);b.put(2,0);b.put(2,0);b.put(12,0);b.put(1,1);b.put(8,0);b.put(1,0);b.put(2,0);b.put(5,0);return b.bytes;}
Bytes gop(unsigned seconds=0){Bits b(0xb8);b.put(25,(1u<<12)|(seconds<<6));b.put(1,0);b.put(1,0);return b.bytes;}
Bytes picture(unsigned temporal){Bits b(0);b.put(10,temporal);b.put(3,1);b.put(16,0xffff);b.put(1,0);return b.bytes;}
Bytes coding(){Bits b(0xb5);b.put(4,8);for(unsigned i=0;i<4;++i)b.put(4,1);b.put(2,0);b.put(2,3);for(unsigned i=0;i<9;++i)b.put(1,i==8);b.put(1,0);return b.bytes;}
Bytes quant_with_embedded_picture_prefix(){Bits b(0xb5);b.put(4,3);b.put(1,1);for(unsigned i=0;i<64;++i)b.put(8,0x55);b.put(1,0);b.put(1,0);b.put(1,0);b.bytes[10]=0;b.bytes[11]=0;b.bytes[12]=1;b.bytes[13]=0;return b.bytes;}
void add(Bytes& b,const Bytes& v){b.insert(b.end(),v.begin(),v.end());}
MovieHeaderUnit unit(const Bytes& b){auto p=parse_movie_header_unit(b);check(bool(p.unit),"literal header parse");return std::move(*p.unit);}
RetailMovieRequest request(){return {0,"fixture.sfd",{640,448},MovieViewSelection::normal,MovieViewSelection::normal,MovieRoute::blocking,0,MovieSubtitleLanguage::english,"ENG"};}
struct Source {
 std::shared_ptr<const MovieSourceObservationIdentity> id=std::make_shared<const MovieSourceObservationIdentity>();Bytes bytes;
 std::shared_ptr<const MovieSourceSyntaxPicture> first,second;MovieVideoFrame frame1,frame2;MovieSourceObservationBatch batch;
 std::map<std::uint64_t,std::shared_ptr<const MovieAdmissionCurrent>> currents;
 Source(unsigned seconds=0,unsigned interposed=0){auto a=make(5,0,seconds,interposed);auto b=make(6,1,seconds,interposed);add(bytes,{0,0,1,0xb7});MovieVideoPesSpan pes{0xe0,12,20,20+bytes.size(),0,bytes.size(),16,std::nullopt};
  a->pes=pes;b->pes=pes;a->quarter_pts=b->quarter_pts=4;first=a;second=b;frame1=frame(a);frame2=frame(b);
  auto current=std::make_shared<MovieAdmissionCurrent>();current->source=std::make_shared<MovieAdmissionEpoch>(MovieAdmissionEpoch{"fixture.sfd",id});
  for(const auto& record:{first,second}){
   for(auto at:{record->sequence_es_byte,record->sequence_extension_es_byte,*record->gop_es_byte,record->picture_es_byte,record->coding_extension_es_byte}){
    auto parsed=parse_movie_header_unit(std::span(bytes).subspan(at));check(bool(parsed.unit),"actual fixture current unit parse");
    const auto code=(std::uint32_t(bytes[at])<<24)|(std::uint32_t(bytes[at+1])<<16)|(std::uint32_t(bytes[at+2])<<8)|bytes[at+3];
    MovieVideoPrefixObserved origin{{at,code,movie_prefix_classification(code)},pes,pes.quarter_pts()};
    auto owned=std::make_shared<MovieCurrentHeaderUnit>(MovieCurrentHeaderUnit{origin,at+parsed.unit->consumed_bytes,std::move(*parsed.unit)});
    if(std::holds_alternative<MovieSequenceHeader>(owned->unit.payload))current->sequence=owned;
    else if(std::holds_alternative<MovieSequenceExtension>(owned->unit.payload))current->sequence_extension=owned;
    else if(std::holds_alternative<MovieGopHeader>(owned->unit.payload))current->gop=owned;
    else if(std::holds_alternative<MoviePictureHeader>(owned->unit.payload))current->picture=owned;
    else current->coding=owned;
    currents.emplace(at,std::make_shared<const MovieAdmissionCurrent>(*current));
   }
  }

  batch={"fixture.sfd",id,{}};batch.events.push_back({1,MovieVideoEsObserved{0,bytes.size(),bytes}});prefixes(batch,0,bytes.size());batch.events.push_back({0,MovieDecodedPictureObserved{*frame1.codec_timing.picture_source,*frame1.codec_timing.picture}});batch.events.push_back({0,MovieDecodedPictureObserved{*frame2.codec_timing.picture_source,*frame2.codec_timing.picture}});batch.events.push_back({0,MovieProgramEndObservation{999,4,0}});renumber(batch);
 }
 std::shared_ptr<MovieSourceSyntaxPicture> make(unsigned rate,unsigned temporal,unsigned seconds,unsigned interposed){auto s=std::make_shared<MovieSourceSyntaxPicture>();s->source_key="fixture.sfd";s->identity=id;s->sequence_es_byte=bytes.size();auto seq=sequence(rate);s->sequence=std::get<MovieSequenceHeader>(unit(seq).payload);add(bytes,seq);s->sequence_extension_es_byte=bytes.size();auto ex=extension();s->sequence_extension=std::get<MovieSequenceExtension>(unit(ex).payload);add(bytes,ex);s->gop_es_byte=bytes.size();auto g=gop(seconds);s->gop=std::get<MovieGopHeader>(unit(g).payload);add(bytes,g);s->picture_es_byte=bytes.size();auto p=picture(temporal);s->picture=std::get<MoviePictureHeader>(unit(p).payload);add(bytes,p);if(interposed==1)add(bytes,quant_with_embedded_picture_prefix());else if(interposed==2)add(bytes,picture(temporal+2));s->coding_extension_es_byte=bytes.size();auto c=coding();s->coding=std::get<MoviePictureCodingExtension>(unit(c).payload);add(bytes,c);add(bytes,{0,0,1,1,0x55});return s;}
 void prefixes(MovieSourceObservationBatch& b,std::uint64_t begin,std::uint64_t end)const{
  for(auto at=begin;at+4<=end;++at)if(bytes[at]==0&&bytes[at+1]==0&&bytes[at+2]==1){const auto code=0x100u|bytes[at+3];b.events.push_back({0,MovieVideoPrefixObserved{{at,code,movie_prefix_classification(code)},first->pes,first->pes.quarter_pts()}});}
 }
 static void renumber(MovieSourceObservationBatch& b,std::uint64_t before=0){for(auto& event:b.events)event.sequence=++before;}
 std::shared_ptr<const MovieAdmissionCurrent> current(std::uint64_t at)const{return currents.at(at);}
 MovieVideoFrame frame(const std::shared_ptr<const MovieSourceSyntaxPicture>& s){MovieVideoFrame f;f.source_syntax=s;f.codec_timing.picture_source=MoviePictureSource{0,s->picture_es_byte,s->pes,s->quarter_pts};Mpeg2PictureTiming t;t.packet_picture_offset=s->picture_es_byte;t.sequence={s->sequence.frame_rate_code,0,0,true,640,448,1};t.temporal_reference=s->picture.temporal_reference;t.coding_type=1;t.picture_structure=3;t.progressive_frame=true;f.codec_timing.picture=t;return f;}
};
struct Rig {
 Source source;std::shared_ptr<MovieEligibilityServiceBinding> service;NativeMoviePlaybackContext* context=nullptr;std::unique_ptr<NativeMovieKernelPolicies> policies;
 Rig(MovieNativeTargetRoute route=MovieNativeTargetRoute::descriptor,unsigned seconds=0,unsigned interposed=0):source(seconds,interposed){MovieControlFailure f;MovieServiceClockFailure sf;auto clock=NativeMovieServiceClock::create({30000,1000},sf);check(bool(clock),"service creation");service=MovieEligibilityServiceBinding::create("fixture.sfd",std::move(*clock),f);check(bool(service),"shared actual service binding");auto filter=MovieClockFilterConfig::source_defaults();auto c=NativeMoviePlaybackContext::create({request(),{},service,filter,route,MovieNativeCompletion::video,true,false,true,0,0,0,0},f);check(bool(c),"native context create with deferred real epoch");context=c.get();policies=NativeMovieKernelPolicies::create(request(),MoviePlaybackAudioPresence::absent,{},MovieFrameEligibilityConfig{30000,1000,0,0,MovieFrameEligibilityMode::direct},std::move(c),service,f);check(bool(policies),"real kernel policies/context");check(policies->validate_observation_source(source.id,f)&&policies->validate_audio_format(std::nullopt,f),"actual identity and absent-audio joins");}
 void begin(){MovieControlFailure f;check(policies->pause(true,f)&&policies->begin(request(),0,f),"pause before actual begin");}
 void input(){MovieControlFailure f;check(policies->observe_source(source.batch,f),"actual ordered source observations");}
 void admissions(){MovieControlFailure f;check(context->admit_header({1,source.first->sequence_es_byte,source.current(source.first->sequence_es_byte),std::nullopt,false,true,false},f),"rate-only B3 latch without future GOP use");check(context->admit_header({2,*source.first->gop_es_byte,source.current(*source.first->gop_es_byte),MovieNativeDescriptorRoute::gop,true,false,true},f),"actual GOP zero-temporal timing and baseline before next picture");check(context->admit_header({3,source.second->picture_es_byte,source.current(source.second->picture_es_byte),MovieNativeDescriptorRoute::gop,false,false,false},f),"separate current work rate admitted without relatching owner920");}
};
struct Port final:NativeMoviePlayback {
 Rig& rig;MoviePlaybackSnapshot snapshot;unsigned presented=0,pauses=0,stops=0;
 explicit Port(Rig& r):rig(r){}
 bool pause(bool p,MovieControlFailure& f)noexcept override{++pauses;snapshot.paused=p;return rig.policies->pause(p,f);}
 bool start(std::string_view key,MovieControlFailure& f)noexcept override{return key=="fixture.sfd"&&rig.policies->begin(request(),0,f);}
 bool pump_metadata(MovieControlFailure& f)noexcept override{return rig.policies->pump_metadata(f);}
 bool pump_streams(MovieControlFailure& f)noexcept override{f={};return true;}
 bool take_error(MovieControlFailure& f)noexcept override{f={};return false;}
 bool status(MoviePlaybackStatus& status,MovieControlFailure& f)noexcept override{bool ended=false,ready=false;if(snapshot.decoder_eof&&!rig.policies->end_admitted(snapshot,ended,f))return false;if(ended){status=MoviePlaybackStatus::ended;return true;}if(!rig.policies->ready(snapshot,ready,f))return false;status=ready?MoviePlaybackStatus::playing:MoviePlaybackStatus::preparing;return true;}
 MoviePresentation try_present(MovieControlFailure& f)noexcept override{if(presented==2)return MoviePresentation::no_frame;const auto& frame=presented?rig.source.frame2:rig.source.frame1;bool eligible=false;if(!rig.policies->eligible(frame,snapshot,eligible,f))return MoviePresentation::error;if(!eligible)return MoviePresentation::no_frame;MovieGpuMetadata metadata;metadata.codec_timing=frame.codec_timing;if(!rig.policies->video_submitted(metadata,f))return MoviePresentation::error;++presented;return MoviePresentation::presented;}
 bool apply_fade_volume(const MovieFadeStep&,MovieControlFailure& f)noexcept override{f={MovieControlError::native_service,"fixture has no fade request",0};return false;}
 bool stop(MovieControlFailure& f)noexcept override{++stops;return rig.policies->stop(f);}
};
